import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-screenshot-modal',
  templateUrl: './screenshot-modal.component.html',
  styleUrls: ['./screenshot-modal.component.scss']
})
export class ScreenshotModalComponent {
  @Input() isOpen = false;
  @Input() appType = '';
  @Output() closeModal = new EventEmitter<void>();

  get screenshotPath(): string {
    return `assets/images/samples/${this.appType}-sample.jpg`;
  }

  get appName(): string {
    switch (this.appType) {
      case 'apple-health':
        return 'Apple Health';
      case 'fitbit':
        return 'Fitbit';
      case 'samsung-health':
        return 'Samsung Health';
      default:
        return 'Health App';
    }
  }

  get appDescription(): string {
    switch (this.appType) {
      case 'apple-health':
        return 'Steps: 8,234 | Calories: 1,586';
      case 'fitbit':
        return 'Steps: 12,456 | Calories: 2,340';
      case 'samsung-health':
        return 'Steps: 9,876 | Calories: 1,890';
      default:
        return 'Sample health data';
    }
  }

  onClose(): void {
    this.closeModal.emit();
  }

  onBackdropClick(event: Event): void {
    if (event.target === event.currentTarget) {
      this.onClose();
    }
  }
}
<!-- Modal Backdrop -->
<div 
  *ngIf="isOpen" 
  class="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4"
  (click)="onBackdropClick($event)"
>
  <!-- Modal Content -->
  <div class="bg-gradient-to-br from-cyan/95 to-dark-cyan/90 backdrop-blur-sm rounded-2xl shadow-2xl border border-cyan/30 max-w-4xl w-full max-h-[90vh] overflow-hidden">
    <!-- Modal Header -->
    <div class="flex items-center justify-between p-4 sm:p-6 border-b border-white/20">
      <div class="flex items-center space-x-3">
        <div class="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center">
          <svg class="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"/>
          </svg>
        </div>
        <div>
          <h3 class="text-lg sm:text-xl font-semibold text-white">{{ appName }}</h3>
          <p class="text-white/70 text-sm">{{ appDescription }}</p>
        </div>
      </div>
      
      <button 
        (click)="onClose()" 
        class="w-8 h-8 sm:w-10 sm:h-10 bg-white/10 hover:bg-white/20 rounded-xl flex items-center justify-center transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-cyan/50">
        <svg class="w-5 h-5 sm:w-6 sm:h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
        </svg>
      </button>
    </div>

    <!-- Modal Body -->
    <div class="p-2 sm:p-4">
      <div class="text-center">
        <img 
          [src]="screenshotPath" 
          [alt]="appName + ' Screenshot'"
          class="w-full h-auto rounded-lg shadow-2xl border border-white/20 max-h-[75vh] object-contain mx-auto"
          onerror="this.style.display='none'; this.nextElementSibling.style.display='block';"
        />
        
        <!-- Fallback content if image fails to load -->
        <div class="hidden bg-gradient-to-br from-grey/20 to-dark-grey/30 rounded-lg p-8 sm:p-12 text-center">
          <div class="w-16 h-16 sm:w-20 sm:h-20 bg-white/20 rounded-2xl mx-auto mb-4 sm:mb-6 flex items-center justify-center">
            <svg class="w-8 h-8 sm:w-10 sm:h-10 text-white/60" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"/>
            </svg>
          </div>
          <h4 class="text-lg sm:text-xl font-semibold text-white mb-2">{{ appName }}</h4>
          <p class="text-white/70 text-sm sm:text-base">{{ appDescription }}</p>
          <p class="text-white/60 text-xs sm:text-sm mt-2">Sample screenshot not available</p>
        </div>
      </div>
    </div>

    <!-- Modal Footer -->
    <div class="flex items-center justify-center p-4 sm:p-6 border-t border-white/20">
      <button 
        (click)="onClose()" 
        class="btn-primary text-sm py-2 px-6">
        Close
      </button>
    </div>
  </div>
</div>
